#include <iostream>
#include <vector>
#include <cmath>

struct DT {
    std::vector<double> a; // a[i] is coefficient of x^i
    int n = 0;             // degree of polynomial

    DT() : a(1, 0.0), n(0) {}
    DT(int deg) : a(deg + 1, 0.0), n(deg) {}
};

std::ostream& operator<<(std::ostream& os, const DT& d) {
    for (int i = 0; i <= d.n; ++i) {
        os << d.a[i] << (i == d.n ? "" : " ");
    }
    return os;
}

DT operator-(const DT& d) {
    DT p(d.n);
    for (int i = 0; i <= d.n; ++i) {
        p.a[i] = -d.a[i];
    }
    return p;
}

DT operator+(const DT& d1, const DT& d2) {
    int max_n = std::max(d1.n, d2.n);
    DT res(max_n);
    for (int i = 0; i <= max_n; ++i) {
        double v1 = (i <= d1.n) ? d1.a[i] : 0.0;
        double v2 = (i <= d2.n) ? d2.a[i] : 0.0;
        res.a[i] = v1 + v2;
    }
    int i = max_n;
    while (i > 0 && std::abs(res.a[i]) < 1e-9) {
        --i;
    }
    res.n = i;
    res.a.resize(res.n + 1);
    return res;
}

DT operator-(const DT& d1, const DT& d2) {
    return d1 + (-d2);
}

DT operator*(const DT& d1, const DT& d2) {
    DT res(d1.n + d2.n);
    for (int i = 0; i <= d1.n; ++i) {
        for (int j = 0; j <= d2.n; ++j) {
            res.a[i + j] += d1.a[i] * d2.a[j];
        }
    }
    return res;
}

double operator^(const DT& d, double x) {
    double s = 0.0, t = 1.0;
    for (int i = 0; i <= d.n; ++i) {
        s += d.a[i] * t;
        t *= x;
    }
    return s;
}

int main() {
    // p(x) = 1 + 2x
    DT p(1); p.a[0] = 1.0; p.a[1] = 2.0;
    // q(x) = 3 + 1x
    DT q(1); q.a[0] = 3.0; q.a[1] = 1.0;
    // r(x) = 2 + 4x
    DT r(1); r.a[0] = 2.0; r.a[1] = 4.0;
    // s(x) = 1 + 1x
    DT s(1); s.a[0] = 1.0; s.a[1] = 1.0;

    // f = -(p + q) * (r - s)
    DT f = -(p + q) * (r - s);

    std::cout << "f(x) coefficients: " << f << "\n";

    double x = 2.0;
    double val = f ^ x;
    std::cout << "f(" << x << ") = " << val << "\n";

    return 0;
}
